<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Plus, Search, Upload, ArrowLeft, Refresh, Document, Reading } from '@element-plus/icons-vue'
import { api, ApiError, download } from '../api'
import { useAuth } from '../stores/auth'
import { markdown, formatDate, statusLabel, errorText, notifyError } from '../utils'
import type { Article, DocumentInfo, IndexStatus, Page } from '../types'
const route = useRoute(), router = useRouter(), auth = useAuth()
const reviewing = computed(()=>route.path==='/knowledge/reviews')
const isDocument = computed(()=>route.path.includes('/documents/'))
const creating = computed(()=>route.path.endsWith('/new'))
const editing = computed(()=>route.path.endsWith('/edit'))
const rid = computed(()=>typeof route.params.id==='string'?route.params.id:'')
const listView = computed(()=>!rid.value && !creating.value)
const base = computed(()=>`/api/knowledge/${isDocument.value?'documents':'articles'}`)
const tab = ref('articles'), keyword = ref(''), status = ref(''), indexFilter = ref(''), page = ref(1), total = ref(0), loading = ref(false), busy = ref(false), error = ref(''), saveError = ref(''), conflict = ref(false)
const items = ref<(Article|DocumentInfo)[]>([]), item = ref<Article|DocumentInfo|null>(null), index = ref<IndexStatus|null>(null), indexError = ref('')
const form = reactive({title:'',content:'',scope:'PUBLIC'}), selectedFile = ref<File|null>(null), fileInput = ref<HTMLInputElement>(), replaceInput = ref<HTMLInputElement>()
const dialog = ref(''), reason = ref(''), indexLoading = ref(false), preview = ref(false)
const canMaintain = computed(()=>!!item.value&&(auth.admin || auth.maintainer && item.value.department.id===auth.user?.department?.id))
const body = computed(()=>item.value && 'content' in item.value?item.value.content:'')
const pending = computed(()=>item.value?.status==='PENDING_REVIEW')
let epoch=0
async function load() {
  const current=++epoch;loading.value=true;error.value='';index.value=null;indexError.value=''
  try {
    if(listView.value) {const result=await api<Page<Article|DocumentInfo>>('GET',`/api/knowledge/${tab.value}`,undefined,{page:page.value,pageSize:10,...(tab.value==='articles'?{keyword:keyword.value||undefined}:{fileName:keyword.value||undefined,indexStatus:indexFilter.value||undefined}),status:reviewing.value?'PENDING_REVIEW':status.value||undefined});if(current!==epoch)return;items.value=result.records;total.value=result.total}
    else if(rid.value){const result=await api<Article|DocumentInfo>('GET',`${base.value}/${rid.value}`);if(current!==epoch)return;item.value=result;if(!conflict.value){form.title=result.title;form.scope=result.scope;form.content='content' in result?result.content:''}if(canMaintain.value)void loadIndex()}
  }catch(e){if(current===epoch)error.value=errorText(e)}finally{if(current===epoch)loading.value=false}
}
async function loadIndex(){if(!rid.value)return;indexLoading.value=true;indexError.value='';try{index.value=await api('GET',`${base.value}/${rid.value}/index-status`)}catch(e){indexError.value=errorText(e)}finally{indexLoading.value=false}}
function search(){page.value=1;void load()}
function changeFile(event:Event,replace=false){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(!/\.(txt|md|markdown)$/i.test(file.name)||file.size===0||file.size>10*1024*1024){ElMessage.warning('请选择 10 MiB 以内的 TXT 或 Markdown 文件');(event.target as HTMLInputElement).value='';return}selectedFile.value=file;if(replace){dialog.value='replace';saveError.value=''}else if(!form.title)form.title=file.name.replace(/\.[^.]+$/,'')}
async function save(){
  saveError.value='';if(!form.title.trim()){saveError.value='请填写知识标题';return}if(!isDocument.value&&!form.content.trim()){saveError.value='请填写文章正文';return}if(isDocument.value&&creating.value&&!selectedFile.value){saveError.value='请选择文档文件';return}
  busy.value=true
  try{
    let result:Article|DocumentInfo
    if(isDocument.value&&creating.value){const data=new FormData();data.append('file',selectedFile.value!);data.append('title',form.title);data.append('scope',form.scope);result=await api('POST',base.value,data)}
    else result=await api(creating.value?'POST':'PATCH',creating.value?base.value:`${base.value}/${rid.value}`,{title:form.title,scope:form.scope,...(!isDocument.value?{content:form.content}:{}),...(!creating.value?{version:item.value!.version}:{})})
    conflict.value=false;ElMessage.success(creating.value?'知识草稿已创建':'草稿已保存');await router.push(`/knowledge/${isDocument.value?'documents':'articles'}/${result.id}`);await load()
  }catch(e){saveError.value=errorText(e);conflict.value=e instanceof ApiError&&e.status===409}finally{busy.value=false}
}
async function refreshPreserving(){conflict.value=true;await load();conflict.value=false;saveError.value='已刷新当前版本，输入已保留。请核对状态后重新保存。'}
function openAction(action:string){dialog.value=action;reason.value='';saveError.value=''}
async function execute(){
  if(!item.value)return
  saveError.value='';if(['reject','withdraw'].includes(dialog.value)&&!reason.value.trim()){saveError.value='请填写原因';return}busy.value=true
  try{
    const path=`${base.value}/${rid.value}`,version=item.value.version
    if(dialog.value==='replace'){if(!selectedFile.value)throw new Error('请选择替换文件');const data=new FormData();data.append('file',selectedFile.value);data.append('version',String(version));await api('PUT',`${path}/file`,data)}
    else if(dialog.value==='delete')await api('DELETE',path,{version})
    else await api('POST',`${path}/${dialog.value}`,{version,...(dialog.value==='approve'?{comment:reason.value}:['reject','withdraw'].includes(dialog.value)?{reason:reason.value}:{})})
    const removed=dialog.value==='delete';dialog.value='';conflict.value=false;ElMessage.success('操作已完成');if(removed)await router.push('/knowledge');else await load()
  }catch(e){saveError.value=errorText(e);conflict.value=e instanceof ApiError&&e.status===409}finally{busy.value=false}
}
async function reindex(){if(!item.value)return;indexLoading.value=true;try{await api('POST',`${base.value}/${rid.value}/reindex`,{contentVersion:item.value.version});ElMessage.success('索引任务已接受，请刷新查看实际结果');await loadIndex()}catch(e){notifyError(e)}finally{indexLoading.value=false}}
async function getFile(){if(!item.value||!('fileName'in item.value))return;try{await download(`${base.value}/${rid.value}/file`,item.value.fileName)}catch(e){notifyError(e)}}
async function leave(){if((creating.value||editing.value)&&(form.title||form.content||selectedFile.value))try{await ElMessageBox.confirm('未保存的输入将不会保留，确认返回？','返回知识库',{confirmButtonText:'确认返回',cancelButtonText:'继续编辑'})}catch{return}await router.push('/knowledge')}
watch(()=>route.fullPath,()=>{item.value=null;form.title='';form.content='';form.scope='PUBLIC';selectedFile.value=null;conflict.value=false;saveError.value='';dialog.value='';page.value=1;void load()},{immediate:true})
</script>
<template><div class="page"><div class="page-header"><div><el-button v-if="!listView" text :icon="ArrowLeft" @click="leave">返回知识库</el-button><h1>{{ listView ? reviewing?'知识审核':'知识库' : creating?isDocument?'上传知识文档':'创建知识文章':editing?'编辑知识草稿':'知识详情' }}</h1><p class="subtitle">{{ reviewing?'核对内容与可见范围，让可靠的经验进入知识库。':'把解决问题的方法留下，让下一次协作更轻松。' }}</p></div><div v-if="listView&&auth.maintainer&&!reviewing" class="actions"><RouterLink to="/knowledge/articles/new"><el-button type="primary" :icon="Plus">写文章</el-button></RouterLink><RouterLink to="/knowledge/documents/new"><el-button :icon="Upload">上传文档</el-button></RouterLink></div></div><el-alert v-if="error" :title="error" type="error" :closable="false"><template #default><el-button text @click="load">重新加载</el-button></template></el-alert>
<section v-if="listView" class="surface" v-loading="loading"><el-tabs v-model="tab" @tab-change="search"><el-tab-pane label="知识文章" name="articles"/><el-tab-pane label="知识文档" name="documents"/></el-tabs><div class="toolbar"><el-input v-model="keyword" :prefix-icon="Search" clearable placeholder="搜索知识标题或文件名" @keyup.enter="search" @clear="search"/><el-select v-if="auth.maintainer&&!reviewing" v-model="status" clearable placeholder="全部状态" @change="search"><el-option v-for="s in ['DRAFT','PENDING_REVIEW','PUBLISHED']" :key="s" :label="statusLabel(s)" :value="s"/></el-select><el-select v-if="auth.maintainer&&tab==='documents'" v-model="indexFilter" clearable placeholder="全部索引状态" @change="search"><el-option v-for="s in ['NOT_INDEXED','PENDING','PROCESSING','SUCCESS','FAILED']" :key="s" :label="s==='PENDING'?'待处理':statusLabel(s)" :value="s"/></el-select><el-button @click="search">查询</el-button><el-button :icon="Refresh" aria-label="刷新知识" @click="load"/></div><div class="count-line">共 {{ total }} 条{{ reviewing?'待审核':'' }}内容</div><el-table :data="items" empty-text="暂无符合条件的知识内容"><el-table-column label="知识内容" min-width="280"><template #default="{row}"><RouterLink class="knowledge-title" :to="`/knowledge/${tab}/${row.id}`"><el-icon><component :is="tab==='articles'?Reading:Document"/></el-icon>{{ row.title }}</RouterLink><p class="knowledge-meta">{{ 'fileName'in row ? `${row.fileName} · ${(row.sizeBytes/1024).toFixed(1)} KB` : `作者 ${row.author.name}` }}</p></template></el-table-column><el-table-column label="状态" width="110"><template #default="{row}"><span class="status" :class="row.status">{{ statusLabel(row.status) }}</span></template></el-table-column><el-table-column label="可见范围" width="130"><template #default="{row}">{{ row.scope==='PUBLIC'?'全员可见':row.department.name }}</template></el-table-column><el-table-column label="更新时间" width="140"><template #default="{row}">{{ formatDate(row.updatedAt) }}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><RouterLink :to="`/knowledge/${tab}/${row.id}`">{{ reviewing?'审核内容':'查看详情' }}</RouterLink></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="total" :page-size="10" layout="prev,pager,next" @current-change="load"/></section>
<div v-else-if="creating||editing" class="detail-grid"><section class="surface" v-loading="loading"><el-alert v-if="saveError" :title="saveError" type="warning" :closable="false"><template #default><el-button v-if="conflict" text @click="refreshPreserving">刷新版本并保留输入</el-button></template></el-alert><el-alert v-if="editing&&item?.status!=='DRAFT'" title="当前内容不是草稿，不能直接修改，请返回详情核对状态。" type="warning" :closable="false"/><el-form label-position="top" :disabled="loading||busy||editing&&!item" @submit.prevent="save"><el-form-item label="知识标题" required><el-input v-model="form.title" maxlength="200" show-word-limit placeholder="便于同事搜索和理解的标题"/></el-form-item><el-form-item label="可见范围" required><el-radio-group v-model="form.scope"><el-radio value="PUBLIC">全员可见</el-radio><el-radio value="DEPARTMENT">本部门</el-radio></el-radio-group></el-form-item><el-form-item v-if="isDocument" label="文档文件" required><input ref="fileInput" type="file" accept=".txt,.md,.markdown" @change="changeFile($event)"><p class="form-help">仅支持 TXT、Markdown，UTF-8 编码，最大 10 MiB。</p></el-form-item><el-form-item v-else label="文章正文" required><el-input v-model="form.content" type="textarea" :rows="17" placeholder="支持 Markdown，说明适用场景、操作步骤和注意事项。"/></el-form-item><div v-if="preview&&!isDocument" class="prose preview" v-html="markdown(form.content)"/><div class="actions"><el-button type="primary" native-type="submit" :loading="busy" :disabled="conflict||editing&&item?.status!=='DRAFT'">保存草稿</el-button><el-button v-if="!isDocument" @click="preview=!preview">{{ preview?'收起预览':'预览正文' }}</el-button><el-button @click="leave">取消</el-button></div></el-form></section><aside class="stack"><div class="hint"><h3>清楚的知识，更容易被复用</h3><p>先说明适用场景，再按顺序整理操作步骤，最后补充需要联系同事处理的情况。</p><p>草稿仅供维护者查看。提交审核并发布后，才会在对应可见范围内展示。</p></div><div class="hint">本部门：{{ auth.user?.department?.name || '未分配部门' }}。公开范围仅包含已登录用户。</div></aside></div>
<div v-else v-loading="loading"><template v-if="item"><section class="surface knowledge-heading"><div><div class="row"><span class="status" :class="item.status">{{ statusLabel(item.status) }}</span><span class="muted">{{ statusLabel(item.scope) }} · 版本 {{ item.version }}</span></div><h2>{{ item.title }}</h2><p class="muted">{{ item.author.name }} · 更新于 {{ formatDate(item.updatedAt) }}</p></div><div class="actions"><template v-if="canMaintain"><template v-if="item.status==='DRAFT'"><RouterLink v-if="!isDocument" :to="`/knowledge/articles/${item.id}/edit`"><el-button>编辑草稿</el-button></RouterLink><el-button v-else @click="dialog='metadata';form.title=item.title;form.scope=item.scope;saveError=''">编辑资料</el-button><el-button v-if="isDocument" @click="replaceInput?.click()">替换文件</el-button><el-button type="primary" @click="openAction('submit')">提交审核</el-button><el-button type="danger" plain @click="openAction('delete')">删除草稿</el-button></template><el-button v-if="['PENDING_REVIEW','PUBLISHED'].includes(item.status)" @click="openAction('withdraw')">撤回为草稿</el-button></template><template v-if="auth.admin&&pending"><el-button type="primary" @click="openAction('approve')">批准发布</el-button><el-button type="danger" plain @click="openAction('reject')">驳回</el-button></template></div></section><div class="detail-grid"><section class="surface"><template v-if="!isDocument"><article class="prose" v-html="markdown(body)"/><hr v-if="'sourceTicket'in item&&item.sourceTicket" class="section-rule"><p v-if="'sourceTicket'in item&&item.sourceTicket" class="muted">整理自 <RouterLink :to="`/tickets/${item.sourceTicket.id}`">{{ item.sourceTicket.number }}</RouterLink>，源工单访问仍受原权限控制。</p></template><template v-else-if="'fileName'in item"><div class="document-download"><el-icon><Document/></el-icon><h3>{{ item.fileName }}</h3><p class="muted">{{ item.format }} · {{ (item.sizeBytes/1024).toFixed(1) }} KB</p><el-button type="primary" @click="getFile">下载原文件</el-button><p class="form-help">通过受控接口下载，访问权限会重新校验。</p></div></template><template v-if="item.review"><hr class="section-rule"><h3>最近审核</h3><p>{{ item.review.comment || '未填写审核意见' }}</p><p class="muted">{{ item.review.reviewer?.name }} · {{ formatDate(item.review.reviewedAt) }}</p></template></section><aside class="stack"><section class="surface"><h2>内容信息</h2><dl class="key-value"><dt>归属部门</dt><dd>{{ item.department.name }}</dd><dt>可见范围</dt><dd>{{ statusLabel(item.scope) }}</dd><dt>作者</dt><dd>{{ item.author.name }}</dd><dt>创建时间</dt><dd>{{ formatDate(item.createdAt) }}</dd><dt>发布时间</dt><dd>{{ formatDate(item.publishedAt) }}</dd></dl></section><section v-if="canMaintain" class="surface" v-loading="indexLoading"><h2>检索索引</h2><el-alert v-if="indexError" :title="indexError" type="warning" :closable="false"/><p>{{ index?.status==='PENDING'?'待处理':statusLabel(index?.status || 'NOT_INDEXED') }}</p><p v-if="index" class="muted">内容版本 {{ index.contentVersion }} · 重试 {{ index.retryCount }} 次</p><p v-if="index?.errorSummary" class="muted">{{ index.errorSummary }}</p><p class="form-help">发布与索引独立。任务已接受不代表入库成功。</p><div class="actions"><el-button :icon="Refresh" @click="loadIndex">刷新状态</el-button><el-button v-if="item.status==='PUBLISHED'" :disabled="['PENDING','PROCESSING'].includes(index?.status||'')" @click="reindex">重建索引</el-button></div></section></aside></div></template></div>
<input ref="replaceInput" class="hidden-file" type="file" accept=".txt,.md,.markdown" @change="changeFile($event,true)"><el-dialog :model-value="!!dialog" :title="({submit:'提交审核',approve:'批准发布',reject:'驳回内容',withdraw:'撤回为草稿',delete:'删除草稿',replace:'替换文档文件',metadata:'编辑文档资料'} as Record<string,string>)[dialog]" width="550px" :close-on-click-modal="!busy" @close="dialog='' "><el-alert v-if="saveError" :title="saveError" type="warning" :closable="false"><template #default><el-button v-if="conflict" text @click="refreshPreserving">刷新版本并保留输入</el-button></template></el-alert><el-form v-if="dialog==='metadata'" label-position="top"><el-form-item label="标题" required><el-input v-model="form.title" maxlength="200"/></el-form-item><el-form-item label="可见范围"><el-radio-group v-model="form.scope"><el-radio value="PUBLIC">全员可见</el-radio><el-radio value="DEPARTMENT">本部门</el-radio></el-radio-group></el-form-item></el-form><template v-else><p v-if="dialog==='submit'">提交后等待管理员审核，通过后才会发布。</p><p v-if="dialog==='approve'">确认内容准确、可见范围合适后发布，系统会提交索引任务。</p><p v-if="dialog==='withdraw'">撤回后立即停止公开阅读与检索，返回草稿后可继续编辑。</p><p v-if="dialog==='delete'">确认删除该草稿？删除后不再显示在知识列表。</p><p v-if="dialog==='replace'">替换为：{{ selectedFile?.name }}。内容版本会随文件更新。</p><el-form v-if="['approve','reject','withdraw'].includes(dialog)" label-position="top"><el-form-item :label="dialog==='approve'?'审核意见（选填）':'原因'" :required="dialog!=='approve'"><el-input v-model="reason" type="textarea" :rows="4"/></el-form-item></el-form></template><template #footer><el-button :disabled="busy" @click="dialog=''">取消</el-button><el-button :type="['delete','reject'].includes(dialog)?'danger':'primary'" :loading="busy" :disabled="conflict" @click="dialog==='metadata'?save().then(()=>{if(!saveError)dialog='' }):execute()">确认{{ dialog==='metadata'?'保存':'' }}</el-button></template></el-dialog></div></template>
<style scoped>.knowledge-title{display:flex;gap:10px;align-items:center;color:#334e65;font-weight:550}.knowledge-title .el-icon{color:#86a2b4;font-size:19px}.knowledge-meta{font-size:11px;color:#95a1af;margin:8px 0 0 29px}.knowledge-heading{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-bottom:22px}.knowledge-heading h2{font-size:23px;margin:18px 0 9px}.knowledge-heading p{margin-bottom:0}.hidden-file{display:none}.preview{background:#f7f9fb;padding:20px;border-radius:7px;margin-bottom:20px}.document-download{text-align:center;padding:45px 15px}.document-download>.el-icon{font-size:50px;color:#8dafc3;margin-bottom:20px}@media(max-width:1000px){.knowledge-heading{flex-direction:column;align-items:flex-start}}
</style>
